{
  "claim": "For non-headline hyperscaler list-price series outside the 14-day gate, a last-value forecast with zero width at one- and three-day horizons will reduce pinball loss because median changes are sufficiently intermittent that the current blend overpredicts immediate movement.",
  "mechanism": "The hypothesis is that posted-price revisions and offer-composition changes move the published median in discrete steps, with the middle-ranked offers usually remaining stable over the following one to three days. A short-horizon persistence forecast should avoid costly forecast displacement between those steps while retaining the current seven-day forecasts.",
  "spec": {
    "when": {
      "all": [
        {"fact": "cls", "op": "==", "value": "hyperscaler_list"},
        {"fact": "gate14", "op": "==", "value": false},
        {"fact": "in37", "op": "==", "value": false},
        {"fact": "horizon", "op": "<=", "value": 3}
      ]
    },
    "do": {"action": "last_zero"}
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least five series change, headline pooled skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show a rise.",
  "prior_ids_used": [],
  "expects": "The condition selects 462 cells across 20 series. The reported negative short-horizon skills support an expected overall loss reduction, with headline forecasts unchanged. I expect at least 200 cells to change and improvements in both halves, but the supplied aggregates cannot establish those counts, temporal consistency, or the bootstrap threshold."
}
